import { cn } from '@/utils/helpers'
import { ChevronDown, ChevronUp, ChevronsUpDown, Search } from 'lucide-react'
import { useState, useMemo } from 'react'
import type { ReactNode } from 'react'
import { Button } from './Button'
import { formatNumber } from '@/utils/formatters'

export interface Column<T> {
  key: string
  header: string
  render?: (item: T) => ReactNode
  sortable?: boolean
  width?: string
  align?: 'left' | 'center' | 'right'
}

interface DataTableProps<T> {
  columns: Column<T>[]
  data: T[]
  keyExtractor: (item: T) => string
  isLoading?: boolean
  emptyMessage?: string
  searchable?: boolean
  searchPlaceholder?: string
  pageSize?: number
  onRowClick?: (item: T) => void
  className?: string
}

export function DataTable<T>({
  columns,
  data,
  keyExtractor,
  isLoading,
  emptyMessage = 'No data found',
  searchable = false,
  searchPlaceholder = 'Search...',
  pageSize = 25,
  onRowClick,
  className,
}: DataTableProps<T>) {
  const [sortKey, setSortKey] = useState<string | null>(null)
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('asc')
  const [search, setSearch] = useState('')
  const [page, setPage] = useState(0)

  const safeData = Array.isArray(data) ? data : []

  const filtered = useMemo(() => {
    if (!search) return safeData
    const query = search.toLowerCase()
    return safeData.filter((item) =>
      columns.some((col) => {
        const val = (item as Record<string, unknown>)[col.key]
        return String(val).toLowerCase().includes(query)
      })
    )
  }, [safeData, search, columns])

  const sorted = useMemo(() => {
    if (!sortKey) return filtered
    return [...filtered].sort((a, b) => {
      const aVal = (a as Record<string, unknown>)[sortKey]
      const bVal = (b as Record<string, unknown>)[sortKey]
      const cmp = String(aVal).localeCompare(String(bVal), undefined, { numeric: true })
      return sortDir === 'asc' ? cmp : -cmp
    })
  }, [filtered, sortKey, sortDir])

  const totalPages = Math.ceil(sorted.length / pageSize)
  const paged = sorted.slice(page * pageSize, (page + 1) * pageSize)

  const handleSort = (key: string) => {
    if (sortKey === key) {
      setSortDir((d) => (d === 'asc' ? 'desc' : 'asc'))
    } else {
      setSortKey(key)
      setSortDir('asc')
    }
  }

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="h-8 w-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  return (
    <div className={cn('space-y-4', className)}>
      {searchable && (
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
          <input
            type="text"
            placeholder={searchPlaceholder}
            value={search}
            onChange={(e) => { setSearch(e.target.value); setPage(0) }}
            className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
          />
        </div>
      )}

      <div className="overflow-x-auto rounded-lg border border-gray-200">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              {columns.map((col) => (
                <th
                  key={col.key}
                  className={cn(
                    'px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wider',
                    col.sortable && 'cursor-pointer select-none hover:bg-gray-100',
                    col.align === 'right' && 'text-right',
                    col.align === 'center' && 'text-center'
                  )}
                  style={{ width: col.width }}
                  onClick={() => col.sortable && handleSort(col.key)}
                >
                  <span className="inline-flex items-center gap-1">
                    {col.header}
                    {col.sortable && (
                      sortKey === col.key ? (
                        sortDir === 'asc' ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />
                      ) : (
                        <ChevronsUpDown className="h-3 w-3 text-gray-300" />
                      )
                    )}
                  </span>
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {paged.length === 0 ? (
              <tr>
                <td colSpan={columns.length} className="px-4 py-12 text-center text-gray-500">
                  {emptyMessage}
                </td>
              </tr>
            ) : (
              paged.map((item) => (
                <tr
                  key={keyExtractor(item)}
                  className={cn(
                    'hover:bg-gray-50 transition-colors',
                    onRowClick && 'cursor-pointer'
                  )}
                  onClick={() => onRowClick?.(item)}
                >
                  {columns.map((col) => (
                    <td
                      key={col.key}
                      className={cn(
                        'px-4 py-3 text-sm text-gray-700 whitespace-nowrap',
                        col.align === 'right' && 'text-right',
                        col.align === 'center' && 'text-center'
                      )}
                    >
                      {col.render
                        ? col.render(item)
                        : String((item as Record<string, unknown>)[col.key] ?? '')
                      }
                    </td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-gray-500">
            Showing {page * pageSize + 1} to {Math.min((page + 1) * pageSize, sorted.length)} of{' '}
            {formatNumber(sorted.length)}
          </p>
          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setPage((p) => Math.max(0, p - 1))}
              disabled={page === 0}
            >
              Previous
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setPage((p) => Math.min(totalPages - 1, p + 1))}
              disabled={page >= totalPages - 1}
            >
              Next
            </Button>
          </div>
        </div>
      )}
    </div>
  )
}

import { useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuthStore } from '@/store/authSlice'

export function useAuth() {
  const store = useAuthStore()

  useEffect(() => {
    if (store.isAuthenticated && !store.user) {
      store.fetchProfile()
    }
  }, [store.isAuthenticated, store.user])

  return store
}

export function useRequireAuth() {
  const navigate = useNavigate()
  const { isAuthenticated, isLoading, fetchProfile, user } = useAuthStore()

  useEffect(() => {
    if (!isLoading && !isAuthenticated) {
      navigate('/login', { replace: true })
    } else if (isAuthenticated && !user) {
      fetchProfile()
    }
  }, [isAuthenticated, isLoading, navigate, fetchProfile, user])

  return { isAuthenticated, isLoading, user }
}

export function useRedirectIfAuth() {
  const navigate = useNavigate()
  const { isAuthenticated } = useAuthStore()

  useEffect(() => {
    if (isAuthenticated) {
      navigate('/dashboard', { replace: true })
    }
  }, [isAuthenticated, navigate])
}

import { useState, useEffect, useCallback, useRef } from 'react'
import { useSearchParams, useNavigate } from 'react-router-dom'
import { Search, Loader2, ArrowUpRight, AlertCircle, Clock, Shield, Eye, Boxes, Skull, FileX, Bot, Key, Database, Brain, Gauge, X } from 'lucide-react'
import { Card, CardHeader, CardTitle, CardContent, Badge } from '@/components/ui'
import { cn } from '@/utils/helpers'
import { formatRelativeTime } from '@/utils/formatters'
import dashboardService from '@/services/dashboardService'
import type { GlobalSearchResult } from '@/services/dashboardService'

// Module icon + color mapping for search results ΓÇö uses Tailwind classes so dark mode CSS vars apply automatically
const MODULE_VISUALS: Record<string, { icon: React.ReactNode; bgClass: string; textClass: string; border: string }> = {
  llm01: { icon: <Shield className="h-4 w-4" />, bgClass: 'bg-red-50', textClass: 'text-red-600', border: 'border-red-200' },
  llm02: { icon: <Eye className="h-4 w-4" />, bgClass: 'bg-orange-50', textClass: 'text-orange-600', border: 'border-orange-200' },
  llm03: { icon: <Boxes className="h-4 w-4" />, bgClass: 'bg-amber-50', textClass: 'text-amber-600', border: 'border-amber-200' },
  llm04: { icon: <Skull className="h-4 w-4" />, bgClass: 'bg-purple-50', textClass: 'text-purple-600', border: 'border-purple-200' },
  llm05: { icon: <FileX className="h-4 w-4" />, bgClass: 'bg-rose-50', textClass: 'text-rose-600', border: 'border-rose-200' },
  llm06: { icon: <Bot className="h-4 w-4" />, bgClass: 'bg-cyan-50', textClass: 'text-cyan-600', border: 'border-cyan-200' },
  llm07: { icon: <Key className="h-4 w-4" />, bgClass: 'bg-pink-50', textClass: 'text-pink-600', border: 'border-pink-200' },
  llm08: { icon: <Database className="h-4 w-4" />, bgClass: 'bg-teal-50', textClass: 'text-teal-600', border: 'border-teal-200' },
  llm09: { icon: <Brain className="h-4 w-4" />, bgClass: 'bg-yellow-50', textClass: 'text-yellow-600', border: 'border-yellow-200' },
  llm10: { icon: <Gauge className="h-4 w-4" />, bgClass: 'bg-lime-50', textClass: 'text-lime-600', border: 'border-lime-200' },
}

export function GlobalSearchPage() {
  const [searchParams, setSearchParams] = useSearchParams()
  const navigate = useNavigate()
  const initialQuery = searchParams.get('q') || ''
  const [query, setQuery] = useState(initialQuery)
  const [results, setResults] = useState<GlobalSearchResult['results']>([])
  const [totalResults, setTotalResults] = useState(0)
  const [loading, setLoading] = useState(false)
  const [searched, setSearched] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)

  const performSearch = useCallback(async (q: string) => {
    if (!q || q.length < 2) {
      setResults([])
      setTotalResults(0)
      setSearched(false)
      return
    }

    setLoading(true)
    setSearched(true)
    try {
      const data = await dashboardService.globalSearch(q)
      setResults(data.results)
      setTotalResults(data.total_results)
    } catch {
      setResults([])
      setTotalResults(0)
    } finally {
      setLoading(false)
    }
  }, [])

  // Run search on mount if query param exists
  useEffect(() => {
    if (initialQuery) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      performSearch(initialQuery)
    }
    // Focus the input
    inputRef.current?.focus()
  }, [])

  const handleSearch = (q: string) => {
    setQuery(q)
    setSearchParams(q ? { q } : {}, { replace: true })
    performSearch(q)
  }

  // Group results by module
  const groupedResults = results.reduce<Record<string, typeof results>>((acc, r) => {
    if (!acc[r.module_id]) acc[r.module_id] = []
    acc[r.module_id].push(r)
    return acc
  }, {})

  // Module display order
  const moduleOrder = ['llm01','llm02','llm03','llm04','llm05','llm06','llm07','llm08','llm09','llm10']

  return (
    <div className="space-y-6">
      {/* Page Header */}
      <div className="flex items-center gap-2">
        <div className="h-8 w-8 rounded-lg bg-indigo-100 flex items-center justify-center">
          <Search className="h-4 w-4 text-indigo-600" />
        </div>
        <h1 className="text-2xl font-bold text-gray-900">Global Search</h1>
      </div>

      {/* Search input */}
      <div className="relative">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400 pointer-events-none" />
        <input
          ref={inputRef}
          type="text"
          value={query}
          onChange={(e) => handleSearch(e.target.value)}
          placeholder="Search across all OWASP modules... (e.g. api_key, critical, jailbreak)"
          className="w-full pl-12 pr-10 py-3 text-base rounded-xl border border-gray-300 focus:outline-none focus:ring-2 focus:ring-indigo-500/30 focus:border-indigo-500 placeholder:text-gray-400 transition-all shadow-sm"
          autoFocus
        />
        {query && (
          <button
            onClick={() => { setQuery(''); setResults([]); setTotalResults(0); setSearched(false); setSearchParams({}, { replace: true }); inputRef.current?.focus() }
            }
            className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 transition-colors"
          >
            <X className="h-4 w-4" />
          </button>
        )}
      </div>

      {/* Loading state */}
      {loading && (
        <div className="flex items-center justify-center py-16">
          <Loader2 className="h-6 w-6 animate-spin text-indigo-500" />
          <span className="ml-3 text-sm text-gray-500">Searching across all modules...</span>
        </div>
      )}

      {/* Results */}
      {!loading && searched && query.length >= 2 && (
        <>
          {/* Results count */}
          <div className="flex items-center justify-between">
            <p className="text-sm text-gray-500">
              {totalResults > 0 ? (
                <>Found <span className="font-semibold text-gray-900">{totalResults}</span> result{totalResults !== 1 ? 's' : ''} for "<span className="font-medium text-gray-700">{query}</span>"</>
              ) : (
                <>No results found for "<span className="font-medium text-gray-700">{query}</span>"</>
              )}
            </p>
          </div>

          {/* Grouped results */}
          {totalResults === 0 ? (
            <div className="bg-white rounded-xl border border-gray-200 p-12 text-center">
              <Search className="h-10 w-10 text-gray-300 mx-auto mb-3" />
              <h3 className="text-lg font-semibold text-gray-900 mb-1">No matching records found</h3>
              <p className="text-sm text-gray-500">Try different keywords like "critical", "api_key", "jailbreak", or "GPT-4"</p>
            </div>
          ) : (
            <div className="space-y-4">
              {moduleOrder.map((modId) => {
                const modResults = groupedResults[modId]
                if (!modResults) return null
                const visual = MODULE_VISUALS[modId]
                const modInfo = modResults[0]
                return (
                  <Card key={modId} className="overflow-hidden">
                    <CardHeader className={cn('border-b bg-gray-50/50', visual?.border || 'border-gray-200')}>
                      <div className="flex items-center gap-2">
                        <div
                          className={cn('h-7 w-7 rounded-lg flex items-center justify-center', visual?.bgClass || 'bg-gray-100')}
                        >
                          <span className={visual?.textClass || 'text-gray-500'}>{visual?.icon}</span>
                        </div>
                        <div>
                          <CardTitle className="text-sm">{modInfo.module_number} ΓÇö {modInfo.module_name}</CardTitle>
                        </div>
                        <Badge variant="default" size="sm" className="ml-auto">{modResults.length}</Badge>
                      </div>
                    </CardHeader>
                    <CardContent className="p-0 divide-y divide-gray-50">
                      {modResults.map((r) => (
                        <div
                          key={r.id}
                          onClick={() => navigate(r.detail_url)}
                          className="flex items-center justify-between p-3.5 hover:bg-gray-50 cursor-pointer transition-colors group"
                        >
                          <div className="flex-1 min-w-0 mr-3">
                            <p className="text-sm font-medium text-gray-900 truncate">{r.label}</p>
                            {r.detail && <p className="text-xs text-gray-500 mt-0.5">{r.detail}</p>}
                          </div>
                          <div className="flex items-center gap-3 shrink-0">
                            {r.created_at && (
                              <span className="text-xs text-gray-400 flex items-center gap-1">
                                <Clock className="h-3 w-3" />
                                {formatRelativeTime(r.created_at)}
                              </span>
                            )}
                            <ArrowUpRight className="h-4 w-4 text-gray-300 group-hover:text-gray-600 transition-colors" />
                          </div>
                        </div>
                      ))}
                    </CardContent>
                  </Card>
                )
              })}
            </div>
          )}
        </>
      )}

      {/* Initial state - no search performed yet */}
      {!loading && !searched && !query && (
        <div className="bg-white rounded-xl border border-gray-200 p-12 text-center">
          <Search className="h-12 w-12 text-gray-200 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-gray-900 mb-2">Search across all OWASP modules</h3>
          <p className="text-sm text-gray-500 max-w-md mx-auto">
            Type a keyword to search across all 10 security modules simultaneously.
            Try searching for things like <strong className="text-gray-700">api_key</strong>,{' '}
            <strong className="text-gray-700">critical</strong>,{' '}
            <strong className="text-gray-700">jailbreak</strong>,{' '}
            <strong className="text-gray-700">GPT-4</strong>, or{' '}
            <strong className="text-gray-700">blocked</strong>.
          </p>
          <div className="flex flex-wrap justify-center gap-2 mt-6">
            {['api_key','critical','jailbreak','GPT-4','blocked','injection','poisoning','token','permission','hallucination'].map((suggestion) => (
              <button
                key={suggestion}
                onClick={() => handleSearch(suggestion)}
                className="px-3 py-1.5 text-xs font-medium text-indigo-600 bg-indigo-50 rounded-full border border-indigo-100 hover:bg-indigo-100 transition-colors"
              >
                {suggestion}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Too short query hint */}
      {!loading && searched && query.length === 1 && (
        <div className="flex items-center justify-center gap-2 py-8 text-sm text-gray-400">
          <AlertCircle className="h-4 w-4" />
          <span>Type at least 2 characters to search</span>
        </div>
      )}
    </div>
  )
}

import { useState, useCallback } from 'react'
// eslint-disable-next-line @typescript-eslint/no-unused-vars
import { Shield, AlertCircle, Zap, Search, Bug, FileText, Loader2, Play, Terminal, Bot, CheckCircle2, XCircle, Copy, Check } from 'lucide-react'
import { Card, CardHeader, CardTitle, CardContent, Badge, SeverityBadge, Tabs } from '@/components/ui'
// eslint-disable-next-line @typescript-eslint/no-unused-vars
import { ScanForm } from './components/ScanForm'
import { RiskScoreCard, ResultsSummary, ResultsTable, ModuleStatCard } from './components/ResultsDisplay'
// eslint-disable-next-line @typescript-eslint/no-unused-vars
import { useModuleApi, type PromptInjectionItem, type BatchItem } from '@/hooks/useModuleApi'
import { formatDateTime, formatRelativeTime, capitalize } from '@/utils/formatters'
import { promptInjectionService, type QuickScanResult } from '@/services/moduleService'

// eslint-disable-next-line @typescript-eslint/no-unused-vars
const SCAN_FIELDS = [
  { name: 'prompt_text', label: 'Prompt Text', type: 'textarea' as const, placeholder: 'Enter the prompt text to analyze for injection attacks...', required: true, rows: 6 },
  { name: 'context', label: 'Additional Context', type: 'textarea' as const, placeholder: 'Optional: provide context about the application or expected behavior...', rows: 3 },
]

const INJECTION_TYPES = [
  { value: 'jailbreak', label: 'Jailbreak Attempt', icon: <Bug className="h-4 w-4" /> },
  { value: 'direct', label: 'Direct Injection', icon: <Zap className="h-4 w-4" /> },
  { value: 'indirect', label: 'Indirect Injection', icon: <Search className="h-4 w-4" /> },
  { value: 'payload_splitting', label: 'Payload Splitting', icon: <FileText className="h-4 w-4" /> },
]


export function PromptInjectionPage() {
  const [isScanning, setIsScanning] = useState(false)
  const [submitError, setSubmitError] = useState<string | null>(null)
  const [submitSuccess, setSubmitSuccess] = useState<string | null>(null)
  const [activeTab, setActiveTab] = useState('scans')
  const [selectedScan, setSelectedScan] = useState<PromptInjectionItem | null>(null)

  // Quick Scan state
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const [quickPrompt, setQuickPrompt] = useState('')
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const [quickModel, setQuickModel] = useState('tinyllama')
  const [isQuickScanning, setIsQuickScanning] = useState(false)
  const [quickResult, setQuickResult] = useState<QuickScanResult | null>(null)
  const [quickError, setQuickError] = useState<string | null>(null)
  const [availableModels, setAvailableModels] = useState<string[]>([])
  const [modelsLoading, setModelsLoading] = useState(false)
  const [copiedSection, setCopiedSection] = useState<string | null>(null)
  

  // Promptfoo state
  const [promptfooPurpose, setPromptfooPurpose] = useState('An AI assistant')
  const [promptfooTargetType, setPromptfooTargetType] = useState('ollama')
  const [promptfooOllamaModel, setPromptfooOllamaModel] = useState('')
  const [isPromptfooScanning, setIsPromptfooScanning] = useState(false)
   
  const [promptfooResult, setPromptfooResult] = useState<any | null>(null)
  const [promptfooError, setPromptfooError] = useState<string | null>(null)
  const [isTestingModel, setIsTestingModel] = useState(false)
  const [testModelResponse, setTestModelResponse] = useState<string | null>(null)
  const [testModelError, setTestModelError] = useState<string | null>(null)

  const copyToClipboard = useCallback(async (text: string, section: string) => {
    try {
      await navigator.clipboard.writeText(text)
      setCopiedSection(section)
      setTimeout(() => setCopiedSection(null), 2000)
    } catch {
      // Fallback for older browsers
      const textarea = document.createElement('textarea')
      textarea.value = text
      document.body.appendChild(textarea)
      textarea.select()
      document.execCommand('copy')
      document.body.removeChild(textarea)
      setCopiedSection(section)
      setTimeout(() => setCopiedSection(null), 2000)
    }
  }, [])

  const formatQuickResults = useCallback(() => {
    if (!quickResult) return ''
    return `=== Quick Scan Results ===

Model: ${quickResult.model_name}
Prompt: ${quickResult.prompt_text}
Model Response: ${quickResult.model_response}

--- Prompt Scan ---
Status: ${quickResult.prompt_scan.is_malicious ? 'MALICIOUS' : 'Safe'}
Risk Score: ${Number(quickResult.prompt_scan.risk_score).toFixed(1)}/100
Injection Type: ${quickResult.prompt_scan.injection_type}
Detections: ${quickResult.prompt_scan.detection_count}
Techniques: ${quickResult.prompt_scan.techniques_detected.join(', ') || 'none'}

--- Response Scan ---
Status: ${quickResult.response_scan.is_malicious ? 'MALICIOUS' : 'Safe'}
// eslint-disable-next-line @typescript-eslint/no-explicit-any
Risk Score: ${Number(quickResult.response_scan.risk_score).toFixed(1)}/100
// eslint-disable-next-line @typescript-eslint/no-explicit-any
Injection Type: ${quickResult.response_scan.injection_type}
Detections: ${quickResult.response_scan.detection_count}
Techniques: ${quickResult.response_scan.techniques_detected.join(', ') || 'none'}
`
  }, [quickResult])

   
   
   
  const { data: scanResults, isLoading, createItem } = useModuleApi<any>('/prompt-injection/scans/')
   
  const { data: batches, isLoading: batchesLoading } = useModuleApi<any>('/prompt-injection/batches/')

  const handleScan = async (data: Record<string, any>) => {
    if (isScanning) return
    setIsScanning(true)
    setSubmitError(null)
    setSubmitSuccess(null)
    try {
       
      const created = await createItem({
        prompt_text: data.prompt_text as string,
      })
      if (created) {
        setSelectedScan(created)
        setActiveTab('scans')
        // Removing premature setSubmitSuccess
      } else {
        setSubmitError('Failed to run scan. Please check the network or server logs.')
      }
     
    } catch (err: any) {
      const msg = err.response?.data?.error || err.response?.data?.detail || err.message || 'An unexpected error occurred.'
      setSubmitError(msg)
    } finally {
      setIsScanning(false)
    }
  }

  const fetchModels = useCallback(async () => {
    setModelsLoading(true)
    try {
      const result = await promptInjectionService.fetchModels()
      setAvailableModels(result.models)
      setPromptfooOllamaModel((prev) => {
        if (result.models.length > 0 && (!prev || !result.models.includes(prev))) {
          return result.models[0]
        }
        return prev
      })
    } catch {
      setAvailableModels([])
      setPromptfooOllamaModel('')
      setTestModelError('Failed to load Ollama models. Is Ollama running?')
    } finally {
      setModelsLoading(false)
    }
  }, [])

  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const handleQuickScan = useCallback(async () => {
    if (!quickPrompt.trim() || !quickModel.trim()) return
    setIsQuickScanning(true)
    setQuickResult(null)
    setQuickError(null)
    try {
      const result = await promptInjectionService.quickScan({
        prompt_text: quickPrompt,
        model_name: quickModel,
      })
      setQuickResult(result)
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Quick scan failed'
      setQuickError(msg)
    } finally {
      setIsQuickScanning(false)
    }
  }, [quickPrompt, quickModel])

  const handlePromptfooScan = useCallback(async () => {
    if (!promptfooPurpose.trim()) return
     
    if (promptfooTargetType === 'ollama' && !promptfooOllamaModel.trim()) return
    setIsPromptfooScanning(true)
    setPromptfooResult(null)
    setPromptfooError(null)
    try {
      const result = await promptInjectionService.promptfooScan({
        purpose: promptfooPurpose,
        target_type: promptfooTargetType,
        ollama_model: promptfooOllamaModel,
      })
      setPromptfooResult(result)
      setActiveTab('scans')
     
    } catch (err: any) {
      const msg = err.response?.data?.error || err.response?.data?.detail || err.message || 'Promptfoo scan failed'
      setPromptfooError(msg)
    } finally {
      setIsPromptfooScanning(false)
    }
  }, [promptfooPurpose, promptfooTargetType, promptfooOllamaModel])

  const maliciousScans = scanResults.filter((s) => s.is_malicious)
  const safeScans = scanResults.filter((s) => !s.is_malicious)
  const criticalCount = scanResults.filter((s) => s.risk_score >= 80).length
  const highCount = scanResults.filter((s) => s.risk_score >= 60 && s.risk_score < 80).length
  const avgRisk = scanResults.length > 0
    ? Math.round(scanResults.reduce((a, s) => a + (typeof s.risk_score === 'number' ? s.risk_score : Number(s.risk_score)), 0) / scanResults.length)
    : 0
  const uniqueTypes = new Set(scanResults.map((s) => s.injection_type)).size

  const tableColumns = [
    { key: 'prompt_text', label: 'Prompt', sortable: true, render: (v: any) => <span className="max-w-[250px] block truncate font-mono text-xs">{v as string}</span> },
    { key: 'injection_type', label: 'Type', sortable: true, render: (v: any) => <Badge variant={v === 'none' || !v ? 'success' : 'danger'}>{capitalize(v as string || 'any')}</Badge> },
    { key: 'is_malicious', label: 'Malicious', render: (v: any) => v ? <span className="text-red-500 font-medium">Yes</span> : <span className="text-green-500 font-medium">No</span> },
    { key: 'risk_score', label: 'Risk', sortable: true, render: (v: any) => {
      const score = typeof v === 'number' ? v : Number(v) || 0
      return <SeverityBadge severity={score >= 80 ? 'critical' : score >= 60 ? 'high' : score >= 40 ? 'medium' : 'low'} />
    }},
    { key: 'created_at', label: 'Time', sortable: true, render: (v: any) => <span className="text-xs text-gray-500">{formatRelativeTime(v as string)}</span> },
  ]

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <div className="flex items-center gap-2">
            <div className="h-8 w-8 rounded-lg bg-red-100 flex items-center justify-center">
              <Shield className="h-4 w-4 text-red-600" />
            </div>
            <Badge variant="danger" size="sm">LLM01</Badge>
            <h1 className="text-2xl font-bold text-gray-900">Prompt Injection</h1>
          </div>
          <p className="text-sm text-gray-500 mt-1 ml-10">
            Detect and prevent prompt injection attacks, jailbreak attempts, and manipulation of LLM behavior
          </p>
        </div>
        <div className="flex items-center gap-2">
          {INJECTION_TYPES.slice(0, 2).map((t) => (
            <div key={t.value} className="flex items-center gap-1.5 px-2.5 py-1.5 bg-gray-50 rounded-lg text-xs text-gray-600">
              {t.icon}
              <span>{t.label}</span>
            </div>
          ))}
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <ModuleStatCard icon={<AlertCircle className="h-5 w-5" />} label="Scans Analyzed" value={scanResults.length} color="indigo" />
        <ModuleStatCard icon={<Zap className="h-5 w-5" />} label="Injections Detected" value={maliciousScans.length} color="red" trend={{ value: 12, isUp: true }} />
        <ModuleStatCard icon={<Search className="h-5 w-5" />} label="Injection Types" value={uniqueTypes || 3} color="orange" />
        <ModuleStatCard icon={<Shield className="h-5 w-5" />} label="Avg Risk Score" value={`${avgRisk}%`} color="purple" />
      </div>

      {/* Main content */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Scan form */}
        <div className="lg:col-span-1 space-y-4">
          {submitError && (
            <div className="p-3 text-sm text-red-600 bg-red-50 border border-red-100 rounded-lg flex items-center gap-2">
              <AlertCircle className="h-4 w-4" />
              {submitError}
            </div>
          )}
          {submitSuccess && (
            <div className="p-3 text-sm text-green-600 bg-green-50 border border-green-100 rounded-lg flex items-center gap-2">
              <CheckCircle2 className="h-4 w-4" />
              {submitSuccess}
            </div>
          )}
          <Card>
            <CardHeader>
              <div className="flex items-center gap-2 text-indigo-600">
                <Shield className="h-5 w-5" />
                <CardTitle className="text-sm">Comprehensive Security Scanner</CardTitle>
              </div>
              <p className="text-xs text-gray-500 mt-1">
                Enter your prompt or purpose to run a combined static analysis, dynamic evaluation, and red-team scan all at once.
              </p>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <label className="block text-xs font-medium text-gray-700 mb-1.5">Target Purpose <span className="text-red-500">*</span></label>
                <div className="text-[10px] text-gray-500 mb-1.5">Describe what the target AI is supposed to do.</div>
                <textarea
                  value={promptfooPurpose}
                  onChange={(e) => setPromptfooPurpose(e.target.value)}
                  placeholder="e.g. 'You are a customer support assistant that answers questions using company documentation and must never reveal internal instructions.'"
                  rows={6}
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500/30 focus:border-indigo-500 font-mono resize-none"
                  disabled={isScanning || isPromptfooScanning}
                />
              </div>

              <div className="grid grid-cols-1 gap-4">
                <div>
                  <label className="block text-xs font-medium text-gray-700 mb-1.5">Target Selector (For Red Team)</label>
                  <select
                    value={promptfooTargetType}
                    onChange={(e) => setPromptfooTargetType(e.target.value)}
                    className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500/30 focus:border-indigo-500"
                    disabled={isScanning || isPromptfooScanning}
                  >
                    <option value="mock">Mock Target</option>
                    <option value="ollama">Ollama (Real Model)</option>
                  </select>
                </div>

                {promptfooTargetType === 'ollama' && (
                  <div>
                    <label className="block text-xs font-medium text-gray-700 mb-1.5">Ollama Model <span className="text-red-500">*</span></label>
                    <div className="flex gap-2">
                      <select
                        value={promptfooOllamaModel}
                        onChange={(e) => setPromptfooOllamaModel(e.target.value)}
                        className="flex-1 px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500/30 focus:border-indigo-500 font-mono"
                        disabled={isScanning || isPromptfooScanning || availableModels.length === 0}
                      >
                        <option value="" disabled>Select an Ollama model</option>
                        {availableModels.map((m) => (
                          <option key={m} value={m}>
                            {m}
                          </option>
                        ))}
                      </select>
                      <button type="button" onClick={fetchModels} className="px-2.5 py-2 text-xs font-medium text-indigo-600 bg-indigo-50 rounded-lg hover:bg-indigo-100 transition-colors shrink-0">
                        {modelsLoading ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : 'Refresh Models'}
                      </button>
                    </div>
                    <div className="mt-2 flex items-center gap-3">
                      // eslint-disable-next-line @typescript-eslint/no-explicit-any
                      <button 
                        type="button" 
                        onClick={async () => {
                          if (!promptfooOllamaModel.trim()) return;
                          setIsTestingModel(true);
                          setTestModelError(null);
                          setTestModelResponse(null);
                          try {
                            const res = await promptInjectionService.testOllamaInference({
                              model: promptfooOllamaModel,
                              prompt: "Reply with: Ollama connection successful."
                            });
                            setTestModelResponse(res.response);
                           
                          } catch (err: any) {
                            setTestModelError(err.response?.data?.error || err.message || 'Test failed');
                          } finally {
                            setIsTestingModel(false);
                          }
                        }}
                        disabled={!promptfooOllamaModel.trim() || isTestingModel}
                        className="px-3 py-1.5 text-xs font-medium text-gray-700 bg-gray-100 rounded-md hover:bg-gray-200 disabled:opacity-50"
                      >
                        {isTestingModel ? 'Testing...' : 'Test Model'}
                      </button>
                    </div>
                    {testModelResponse && (
                      <div className="mt-2 p-2 bg-green-50 text-green-800 border border-green-200 rounded text-xs font-mono whitespace-pre-wrap">
                        {testModelResponse}
                      </div>
                    )}
                    {testModelError && (
                      <div className="mt-2 p-2 bg-red-50 text-red-800 border border-red-200 rounded text-xs font-mono">
                        {testModelError}
                      </div>
                    )}
                  </div>
                )}
              </div>

              <div className="flex flex-col gap-3 pt-2">
                <button
                  onClick={async () => {
                    // Trigger Static Analysis
                    handleScan({ prompt_text: promptfooPurpose });
                    
                     
                    // Trigger Red Team Scan
                    handlePromptfooScan();
                    
                    // Trigger Quick Scan (if Ollama is selected)
                    if (promptfooTargetType === 'ollama' && promptfooOllamaModel.trim()) {
                      setIsQuickScanning(true);
                      setQuickResult(null);
                      setQuickError(null);
                      try {
                        const result = await promptInjectionService.quickScan({
                          prompt_text: promptfooPurpose,
                          model_name: promptfooOllamaModel,
                        });
                        setQuickResult(result);
                       
                      } catch (err: any) {
                        setQuickError(err.message || 'Quick scan failed');
                      } finally {
                        setIsQuickScanning(false);
                      }
                    }
                  }}
                  disabled={isScanning || isPromptfooScanning || isQuickScanning || !promptfooPurpose.trim() || (promptfooTargetType === 'ollama' && !promptfooOllamaModel.trim())}
                  className="w-full px-4 py-3 text-sm font-medium text-white bg-indigo-600 rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center justify-center gap-2 shadow-sm"
                >
                  {(isScanning || isPromptfooScanning || isQuickScanning) ? (
                    <><Loader2 className="h-5 w-5 animate-spin" /> Running Comprehensive Scan...</>
                  ) : (
                    <><Shield className="h-5 w-5" /> Run Comprehensive Scan</>
                  )}
                </button>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Results */}
        <div className="lg:col-span-2 space-y-4">
          <Tabs
            tabs={[
              { id: 'scans', label: 'Comprehensive Scan Results', content: null },
              { id: 'findings', label: 'Scan History & Findings', content: null },
              { id: 'batches', label: 'Batch Analysis', content: null },
            ]}
            activeTab={activeTab}
            onChange={setActiveTab}
          />

          {activeTab === 'scans' && (
            <div className="space-y-4">
              {promptfooError && (
                <Card>
                  <CardHeader>
                    <div className="flex items-center gap-2 text-red-500">
                      <XCircle className="h-4 w-4" />
                      <CardTitle className="text-sm">Scan Error</CardTitle>
                    </div>
                  </CardHeader>
                  <CardContent>
                    <pre className="bg-red-50 text-red-700 p-3 rounded-lg text-xs font-mono whitespace-pre-wrap">{promptfooError}</pre>
                  </CardContent>
                </Card>
              )}

              {isPromptfooScanning && !promptfooResult && (
                <Card>
                  <CardHeader>
                    <div className="flex items-center gap-2">
                      <Loader2 className="h-4 w-4 text-indigo-500 animate-spin" />
                      <CardTitle className="text-sm">Running Promptfoo...</CardTitle>
                    </div>
                  </CardHeader>
                  <CardContent>
                    <div className="bg-gray-950 text-green-400 p-4 rounded-lg font-mono text-xs space-y-2">
                      <div className="flex items-center gap-2">
                        <Loader2 className="h-3 w-3 animate-spin" />
                        <span>Generating and executing adversarial tests...</span>
                      </div>
                      <div className="text-green-500/50 text-[10px] pt-1 italic">
                        This may take a minute or two as it generates probes and tests the API.
                      </div>
                    </div>
                  </CardContent>
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                </Card>
              )}

              {promptfooResult && promptfooResult.status === 'completed' && (
                <Card>
                  <CardHeader>
                    <CardTitle className="text-sm">Red Team Scan Results</CardTitle>
                    <div className="flex gap-4 text-xs mt-2">
                      <div className="font-medium">Total Tests: {promptfooResult.summary?.total_tests ?? 0}</div>
                      <div className="font-medium text-red-500">Vulnerabilities Found: {promptfooResult.summary?.malicious_found ?? 0}</div>
                      <div className="font-medium text-green-500">Passed: {(promptfooResult.summary?.total_tests ?? 0) - (promptfooResult.summary?.malicious_found ?? 0)}</div>
                    </div>
                  </CardHeader>
                  <CardContent>
                    <div className="max-h-[600px] overflow-y-auto space-y-3">
                      // eslint-disable-next-line @typescript-eslint/no-explicit-any
                      // eslint-disable-next-line @typescript-eslint/no-explicit-any
                      {promptfooResult.results?.map((res: any, idx: number) => {
                        const passed = res.success
                        const pluginId = res.metadata?.pluginId || res.testCase?.metadata?.pluginId || '-'
                        const severity = res.metadata?.severity || res.testCase?.metadata?.severity || '-'
                        const attackPrompt = res.vars?.prompt || res.prompt?.raw || '-'
                        const targetResponse = res.response?.output || '-'
                        const reason = res.gradingResult?.reason || res.error || '-'
                        return (
                          <details key={idx} className={`rounded-lg border ${passed ? 'border-green-200 bg-green-50 dark:bg-green-950/30 dark:border-green-800' : 'border-red-200 bg-red-50 dark:bg-red-950/30 dark:border-red-800'}`}>
                            <summary className="p-3 flex justify-between items-center gap-2 flex-wrap cursor-pointer outline-none hover:bg-black/5 transition-colors">
                              <div className="flex items-center gap-2">
                                <Badge variant={passed ? 'success' : 'danger'}>{passed ? 'Γ£ô Passed' : 'Γ£ù Vulnerable'}</Badge>
                                <span className="text-xs font-semibold text-gray-600 uppercase tracking-wide">Plugin: {pluginId}</span>
                              </div>
                              <div className="flex items-center gap-2">
                                {severity !== '-' && (
                                  <span className={`text-xs font-medium px-1.5 py-0.5 rounded ${severity === 'high' ? 'bg-orange-100 text-orange-700' : severity === 'medium' ? 'bg-yellow-100 text-yellow-700' : 'bg-gray-100 text-gray-600'}`}>
                                    {severity.toUpperCase()} severity
                                  </span>
                                )}
                                <span className="text-xs text-gray-400">Test #{idx + 1}</span>
                              </div>
                            </summary>
                            <div className="p-3 border-t space-y-2 text-xs border-gray-200/50">
                              <div>
                                <span className="font-semibold text-gray-700 block mb-1">Attack Prompt:</span>
                                <div className="font-mono text-gray-800 bg-white/70 dark:bg-black/20 p-2 rounded border border-gray-100 break-words whitespace-pre-wrap max-h-24 overflow-y-auto">
                                  {attackPrompt}
                                </div>
                              </div>
                              <div>
                                <span className="font-semibold text-gray-700 block mb-1">Target LLM Response:</span>
                                <div className="font-mono text-gray-700 bg-white/70 dark:bg-black/20 p-2 rounded border border-gray-100 break-words whitespace-pre-wrap max-h-20 overflow-y-auto">
                                  {targetResponse}
                                </div>
                              </div>
                              <div>
                                <span className={`font-semibold block mb-1 ${passed ? 'text-green-700' : 'text-red-700'}`}>
                                  {passed ? 'Pass Reason:' : 'Vulnerability Reason:'}
                                </span>
                                <div className={`p-2 rounded border break-words whitespace-pre-wrap ${passed ? 'bg-green-50 border-green-200 text-green-800' : 'bg-red-50 border-red-200 text-red-800'}`}>
                                  {reason}
                                </div>
                              </div>
                            </div>
                          </details>
                        )
                      })}
                    </div>
                  </CardContent>
                </Card>
              )}
            </div>
          )}

          {activeTab === 'findings' && (
            <div className="space-y-4">
              <Card>
                <CardHeader>
                  <CardTitle>Active Injection Findings</CardTitle>
                  <Badge variant="danger">{criticalCount + highCount} active issues</Badge>
                </CardHeader>
                <CardContent>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                    {scanResults.filter((s) => s.risk_score >= 60).map((item) => (
                      <div key={item.id} className="p-4 rounded-lg border border-gray-200 bg-white">
                        <div className="flex items-center justify-between mb-2">
                          <SeverityBadge severity={
                            item.risk_score >= 80 ? 'critical' :
                            item.risk_score >= 60 ? 'high' : 'medium'
                          } />
                          <Badge variant={item.is_malicious ? 'danger' : 'success'} size="sm">
                            {item.is_malicious ? 'Malicious' : 'Safe'}
                          </Badge>
                        </div>
                        <p className="text-sm font-medium text-gray-900 truncate mb-1">{item.prompt_text}</p>
                        <p className="text-xs text-gray-500 capitalize">Type: {item.injection_type?.replace(/_/g, ' ') || 'Unknown'}</p>
                        <p className="text-xs text-gray-400 mt-1">{formatRelativeTime(item.created_at)}</p>
                      </div>
                    ))}
                    {scanResults.filter((s) => s.risk_score >= 60).length === 0 && (
                      <div className="col-span-full text-center py-8 text-sm text-gray-400">No critical or high-risk findings at this time</div>
                    )}
                  </div>
                </CardContent>
              </Card>

              {isLoading ? (
                <div className="flex items-center justify-center py-12">
                  <Loader2 className="h-6 w-6 animate-spin text-indigo-500" />
                  <span className="ml-2 text-sm text-gray-500">Loading scan results...</span>
                </div>
              ) : (
                <>
                  <ResultsSummary
                    totalItems={scanResults.length}
                    riskItems={maliciousScans.length}
                    safeItems={safeScans.length}
                    criticalItems={criticalCount}
                    highItems={highCount}
                  />

                  <Card>
                    <CardHeader>
                      <CardTitle>Recent Scan Results</CardTitle>
                    </CardHeader>
                    <CardContent>
                      <ResultsTable
                        columns={tableColumns}
                        data={scanResults as any as Record<string, any>[]}
                        onRowClick={(row) => setSelectedScan(row as any as PromptInjectionItem)}
                      />
                    </CardContent>
                  </Card>

                  {selectedScan && (
                    <Card>
                      <CardHeader>
                        <CardTitle>Scan Detail</CardTitle>
                        <SeverityBadge severity={
                          selectedScan.risk_score >= 80 ? 'critical' :
                          selectedScan.risk_score >= 60 ? 'high' :
                          selectedScan.risk_score >= 40 ? 'medium' : 'low'
                        } />
                      </CardHeader>
                      <CardContent className="space-y-4">
                        <div>
                          <p className="text-xs font-medium text-gray-500 mb-1">Analyzed Prompt</p>
                          <div className="bg-gray-50 rounded-lg p-3 font-mono text-sm text-gray-700 whitespace-pre-wrap">
                            {selectedScan.prompt_text}
                          </div>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                          <RiskScoreCard score={typeof selectedScan.risk_score === 'number' ? selectedScan.risk_score : Number(selectedScan.risk_score)} label="Risk Score" />
                          <div className="space-y-3">
                            <div>
                              <p className="text-xs text-gray-500">Injection Type</p>
                              <p className="text-sm font-medium text-gray-900 capitalize">{selectedScan.injection_type?.replace(/_/g, ' ') || 'Unknown'}</p>
                            </div>
                            <div>
                              <p className="text-xs text-gray-500">Detected At</p>
                              <p className="text-sm font-medium text-gray-900">{formatDateTime(selectedScan.created_at)}</p>
                            </div>
                            <div>
                              <p className="text-xs text-gray-500">Malicious</p>
                              <Badge variant={selectedScan.is_malicious ? 'danger' : 'success'}>
                                {selectedScan.is_malicious ? 'Yes - Action Required' : 'No - Safe'}
                              </Badge>
                            </div>
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  )}
                </>
              )}
            </div>
          )}

          {activeTab === 'batches' && (
            <Card>
              <CardHeader>
                <CardTitle>Batch Analysis</CardTitle>
                <Badge variant="info">{batches.length} batches</Badge>
              </CardHeader>
              <CardContent>
                {batchesLoading ? (
                  <div className="flex items-center justify-center py-12"><Loader2 className="h-6 w-6 animate-spin text-indigo-500" /><span className="ml-2 text-sm text-gray-500">Loading batches...</span></div>
                ) : (
                  <div className="space-y-3">
                    {batches.map((batch) => (
                      <div key={batch.id} className="flex items-center justify-between p-3 rounded-lg bg-gray-50">
                        <div className="flex-1">
                          <p className="text-sm font-medium text-gray-900">{batch.name}</p>
                          <div className="flex items-center gap-3 mt-1 text-xs text-gray-500">
                            <span>{batch.total_prompts} prompts</span>
                            <span className="text-red-500">{batch.malicious_count} malicious</span>
                            <span>Avg risk: {Number(batch.avg_risk_score).toFixed(1)}</span>
                          </div>
                        </div>
                        <div className="flex items-center gap-3">
                          <div className="h-8 w-16 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
                            <div className="h-full bg-red-500 dark:bg-red-600 rounded-full" style={{ width: `${(batch.malicious_count / batch.total_prompts) * 100}%` }} />
                          </div>
                          <span className="text-xs text-gray-500">{formatRelativeTime(batch.created_at)}</span>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          )}

          {activeTab === 'scans' && (
            <div className="space-y-4 mt-8">
              {quickResult && <h3 className="text-lg font-semibold text-gray-800">Dynamic Analysis Results</h3>}

              {/* Error display */}
              {quickError && (
                <Card>
                  <CardHeader>
                    <div className="flex items-center gap-2 text-red-500">
                      <XCircle className="h-4 w-4" />
                      <CardTitle className="text-sm">Scan Error</CardTitle>
                    </div>
                  </CardHeader>
                  <CardContent>
                    <pre className="bg-red-50 text-red-700 p-3 rounded-lg text-xs font-mono whitespace-pre-wrap">{quickError}</pre>
                  </CardContent>
                </Card>
              )}

              {/* Loading state */}
              {isQuickScanning && !quickResult && (
                <Card>
                  <CardHeader>
                    <div className="flex items-center gap-2">
                      <Loader2 className="h-4 w-4 text-indigo-500 animate-spin" />
                      <CardTitle className="text-sm">Running Quick Scan...</CardTitle>
