                            title="Copy prompt scan results"
                            aria-label="Copy prompt scan results"
                          >
                            {copiedSection === 'prompt-scan' ? (
                              <Check className="h-3 w-3 text-green-500" />
                            ) : (
                              <Copy className="h-3 w-3" />
