                        </div>
                        <p className="text-[10px] text-gray-400 mt-0.5">Injection detection on the model's output</p>
                      </CardHeader>
                      <CardContent className="space-y-3">
                        <div className="flex items-center gap-2">
                          <span className="text-xs text-gray-500">Status:</span>
                          {quickResult.response_scan.is_malicious ? (
                            <Badge variant="danger">Malicious</Badge>
                          ) : (
                            <Badge variant="success">Safe</Badge>
                          )}
                        </div>
                        <div className="flex items-center gap-2">
                          <span className="text-xs text-gray-500">Risk Score:</span>
                          <SeverityBadge severity={
                            quickResult.response_scan.risk_score >= 80 ? 'critical' :
                            quickResult.response_scan.risk_score >= 60 ? 'high' :
                            quickResult.response_scan.risk_score >= 40 ? 'medium' : 'low'
                          } />
                          <span className="text-sm font-semibold">{Number(quickResult.response_scan.risk_score).toFixed(1)}</span>
                        </div>
                        <div>
                          <span className="text-xs text-gray-500">Injection Type: </span>
                          <span className="text-sm font-medium capitalize">{quickResult.response_scan.injection_type.replace(/_/g, ' ')}</span>
                        </div>
                        <div>
                          <span className="text-xs text-gray-500">Detections: </span>
                          <span className="text-sm font-medium">{quickResult.response_scan.detection_count}</span>
                        </div>
                        {quickResult.response_scan.techniques_detected.length > 0 && (
                          <div>
                            <span className="text-xs text-gray-500 block mb-1">Techniques:</span>
                            <div className="flex flex-wrap gap-1">
                              {quickResult.response_scan.techniques_detected.map((t: string) => (
                                <Badge key={t} variant="danger" size="sm">{t}</Badge>
                              ))}
                            </div>
                          </div>
                        )}
                      </CardContent>
                    </Card>
                  </div>
                </>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Edit2, Trash2, Plus, Shield } from 'lucide-react'
 
// eslint-disable-next-line @typescript-eslint/no-unused-vars
import { Button, Card, CardHeader, CardTitle, CardContent, Badge, Tabs } from '@/components/ui'
import { DataTable, type Column } from '@/components/ui/DataTable'
import { useOrganizationStore } from '@/store/organizationSlice'
import { formatDate } from '@/utils/formatters'
import { PageLoading } from '@/components/ui/LoadingSpinner'

export function OrganizationDetailPage() {
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()
  const { currentOrganization, members, isLoading, fetchOrganization, fetchMembers, deleteOrganization } = useOrganizationStore()
  const [showInvite, setShowInvite] = useState(false)
  const [showDelete, setShowDelete] = useState(false)

  useEffect(() => {
    if (!id) return
    fetchOrganization(id).catch(() => {})
    fetchMembers(id).catch(() => {})
  }, [id, fetchOrganization, fetchMembers])

  const org = currentOrganization
  const orgMembers = members

  if (isLoading && !org) return <PageLoading />

  if (!org) {
    return (
      <div className="space-y-6">
        <button onClick={() => navigate('/organizations')} className="flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700"><ArrowLeft className="h-4 w-4" /> Back to organizations</button>
        <Card><p className="p-8 text-center text-gray-500">Organization not found.</p></Card>
      </div>
    )
   
  }
  

   
  const memberColumns: Column<any>[] = [
     
    { key: 'user', header: 'User', render: (m: any) => (
      <span className="flex items-center gap-2">
        <div className="h-8 w-8 rounded-full bg-indigo-100 flex items-center justify-center text-xs font-medium text-indigo-700">
          {(m.email || m.user?.email || '?').charAt(0).toUpperCase()}
        </div>
        <div>
          <p className="font-medium">{m.first_name || m.user?.first_name || ''} {m.last_name || m.user?.last_name || ''}</p>
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          <p className="text-xs text-gray-500">{m.email || m.user?.email || ''}</p>
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        </div>
      </span>
    )},
     
    { key: 'role', header: 'Role', render: (m: any) => <Badge variant={m.role === 'owner' ? 'info' : 'default'}>{m.role}</Badge> },
     
    { key: 'joined_at', header: 'Joined', render: (m: any) => formatDate(m.joined_at) },
  ]

  const tabs = [
    {
      id: 'overview',
      label: 'Overview',
      content: (
        <div className="space-y-6">

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <Card><p className="text-2xl font-bold text-gray-900">{orgMembers.length}</p><p className="text-sm text-gray-500">Members</p></Card>
            <Card><p className="text-2xl font-bold text-gray-900 capitalize">{org.subscription_tier}</p><p className="text-sm text-gray-500">Subscription</p></Card>
            <Card><p className="text-2xl font-bold text-gray-900">{formatDate(org.created_at)}</p><p className="text-sm text-gray-500">Created</p></Card>
          </div>
          {org.description && (<Card><CardTitle>Description</CardTitle><p className="text-sm text-gray-600 mt-2">{org.description}</p></Card>)}
        </div>
      ),
    },
    {
       
      id: 'members',
      label: 'Members',
      badge: orgMembers.length,
      content: (
        <div className="space-y-4">
          <div className="flex justify-end"><Button size="sm" onClick={() => setShowInvite(true)}><Plus className="h-4 w-4" /> Invite Member</Button></div>
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          <DataTable columns={memberColumns} data={orgMembers} keyExtractor={(m: any) => m.id} searchable emptyMessage="No members found" />
        </div>
      ),
    },
  ]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button onClick={() => navigate('/organizations')} className="p-2 hover:bg-gray-100 rounded-lg"><ArrowLeft className="h-5 w-5 text-gray-500" /></button>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold text-gray-900">{org.name}</h1>
              <Badge variant={org.is_active ? 'success' : 'default'}>{org.is_active ? 'Active' : 'Inactive'}</Badge>
            </div>
            <p className="text-sm text-gray-500 mt-1">{org.industry || 'No industry'}</p>
          </div>
        </div>
      <div className="flex items-center gap-2">
        <Button variant="outline" size="sm" onClick={() => navigate(`/projects?org=${org?.id}`)}><Shield className="h-4 w-4" /> Projects</Button>
        <Button variant="outline" size="sm" onClick={() => {}}><Edit2 className="h-4 w-4" /> Edit</Button>
        <Button variant="danger" size="sm" onClick={() => setShowDelete(true)}><Trash2 className="h-4 w-4" /> Delete</Button>
      </div>
      </div>

      <Tabs tabs={tabs} />

      {showInvite && <InviteMemberModal orgId={org.id} onClose={() => setShowInvite(false)} />}

      {showDelete && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
          <div className="bg-white rounded-2xl p-6 w-full max-w-sm mx-4 shadow-2xl">
            <h2 className="text-lg font-semibold text-gray-900 mb-2">Delete Organization?</h2>
            <p className="text-sm text-gray-500 mb-4">This will permanently delete <strong>{org.name}</strong> and all associated data.</p>
            <div className="flex justify-end gap-3">
              <Button variant="outline" onClick={() => setShowDelete(false)}>Cancel</Button>
              <Button variant="danger" onClick={async () => { await deleteOrganization(org.id); navigate('/organizations') }}>Delete</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

function InviteMemberModal({ orgId, onClose }: { orgId: string; onClose: () => void }) {
  const { inviteMember, isLoading } = useOrganizationStore()
  const [email, setEmail] = useState('')
  const [role, setRole] = useState('member')

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    await inviteMember(orgId, email, role)
    onClose()
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
      <div className="bg-white rounded-2xl p-6 w-full max-w-md mx-4 shadow-2xl">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">Invite Member</h2>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div><label className="block text-sm font-medium text-gray-700 mb-1">Email</label><input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required placeholder="colleague@company.com" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500" /></div>
          <div><label className="block text-sm font-medium text-gray-700 mb-1">Role</label><select value={role} onChange={(e) => setRole(e.target.value)} className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500"><option value="member">Member</option><option value="admin">Admin</option><option value="viewer">Viewer</option><option value="auditor">Auditor</option></select></div>
          <div className="flex justify-end gap-3"><Button variant="outline" type="button" onClick={onClose}>Cancel</Button><Button type="submit" isLoading={isLoading}>Invite</Button></div>
        </form>
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { Plus, Building2, Users } from 'lucide-react'
import { Button, Card, CardTitle, CardHeader, CardContent, Badge } from '@/components/ui'
import { useOrganizationStore } from '@/store/organizationSlice'
import { formatDate, formatNumber } from '@/utils/formatters'
import { PageLoading } from '@/components/ui/LoadingSpinner'
export function OrganizationListPage() {
  const navigate = useNavigate()
  const { organizations, isLoading, fetchOrganizations } = useOrganizationStore()
  const [showCreate, setShowCreate] = useState(false)

  // Kick off the API fetch on mount
  useEffect(() => {
    fetchOrganizations()
  }, [])

  if (isLoading) return <PageLoading />

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Organizations</h1>
          <p className="text-sm text-gray-500 mt-1">Manage your organizations and teams</p>
        </div>
        <Button onClick={() => setShowCreate(true)}><Plus className="h-4 w-4" /> New Organization</Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        {organizations.map((org: any) => (
          <Card key={org.id} hover onClick={() => navigate(`/organizations/${org.id}`)}>
            <CardHeader>
              <div className="flex items-center gap-3">
                <div className="h-10 w-10 rounded-lg bg-indigo-100 flex items-center justify-center"><Building2 className="h-5 w-5 text-indigo-600" /></div>
                <div>
                  <CardTitle className="text-base">{org.name}</CardTitle>
                  <p className="text-xs text-gray-500">{org.industry || 'No industry set'}</p>
                </div>
              </div>
              <Badge variant={org.is_active ? 'success' : 'default'}>{org.is_active ? 'Active' : 'Inactive'}</Badge>
            </CardHeader>
            <CardContent>
              <p className="text-sm text-gray-600 line-clamp-2 mb-3">{org.description || 'No description'}</p>
              <div className="flex items-center gap-4 text-sm text-gray-500">
                <span className="flex items-center gap-1"><Users className="h-4 w-4" />{formatNumber(org.member_count)} members</span>
                <span>{formatDate(org.created_at)}</span>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {showCreate && <CreateOrganizationModal onClose={() => setShowCreate(false)} />}
    </div>
  )
}

function CreateOrganizationModal({ onClose }: { onClose: () => void }) {
  const { createOrganization, isLoading } = useOrganizationStore()
  const navigate = useNavigate()
  const [name, setName] = useState('')
  const [description, setDescription] = useState('')
  const [industry, setIndustry] = useState('')

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    try {
      const org = await createOrganization({ name, description, industry: industry || undefined })
      navigate(`/organizations/${org.id}`)
      onClose()
    } catch { /* Handle error */ }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
      <div className="bg-white rounded-2xl p-6 w-full max-w-md mx-4 shadow-2xl">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">Create Organization</h2>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div><label className="block text-sm font-medium text-gray-700 mb-1">Name *</label><input type="text" value={name} onChange={(e) => setName(e.target.value)} required placeholder="Acme Corp" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500" /></div>
          <div><label className="block text-sm font-medium text-gray-700 mb-1">Description</label><textarea value={description} onChange={(e) => setDescription(e.target.value)} rows={3} placeholder="Organization description" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500" /></div>
          <div><label className="block text-sm font-medium text-gray-700 mb-1">Industry</label><input type="text" value={industry} onChange={(e) => setIndustry(e.target.value)} placeholder="e.g., Technology, Finance, Healthcare" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500" /></div>
          <div className="flex justify-end gap-3 pt-2"><Button variant="outline" type="button" onClick={onClose}>Cancel</Button><Button type="submit" isLoading={isLoading}>Create</Button></div>
        </form>
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { useNavigate, useSearchParams } from 'react-router-dom'
import { Plus, FolderKanban } from 'lucide-react'
import { Button, Card, CardHeader, CardTitle, CardContent, Badge, EmptyState } from '@/components/ui'
import { useProjectStore } from '@/store/projectSlice'
import { useOrganizationStore } from '@/store/organizationSlice'
import { formatDate } from '@/utils/formatters'
import { PageLoading } from '@/components/ui/LoadingSpinner'
import { cn } from '@/utils/helpers'

export function ProjectListPage() {
  const navigate = useNavigate()
  const [searchParams] = useSearchParams()
  const orgId = searchParams.get('org')
  const { projects, fetchProjects } = useProjectStore()
  const { organizations, isLoading: orgsLoading, fetchOrganizations } = useOrganizationStore()
  const [showCreate, setShowCreate] = useState(false)
  const [selectedOrg, setSelectedOrg] = useState(orgId || '')

  // Kick off orgs fetch
  useEffect(() => {
    fetchOrganizations()
  }, [])

  // Kick off projects fetch when org selected
  useEffect(() => {
    fetchProjects(selectedOrg || undefined).catch(() => {})
  }, [selectedOrg])

  const displayOrgs = organizations
  const displayProjects = projects

  if (orgsLoading && organizations.length === 0) return <PageLoading />

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Projects</h1>
          <p className="text-sm text-gray-500 mt-1">Manage AI security assessment projects</p>
        </div>
        <Button onClick={() => setShowCreate(true)} disabled={!selectedOrg}><Plus className="h-4 w-4" /> New Project</Button>
      </div>



      <div className="flex gap-2 flex-wrap">
        <button onClick={() => setSelectedOrg('')} className={cn('px-4 py-2 rounded-lg text-sm font-medium transition-colors', !selectedOrg ? 'bg-indigo-600 text-white dark:text-[#ffffff]' : 'bg-gray-100 text-gray-600 hover:bg-gray-200')}>All</button>
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        {displayOrgs.map((org: any) => (
          <button key={org.id} onClick={() => setSelectedOrg(org.id)} className={cn('px-4 py-2 rounded-lg text-sm font-medium transition-colors', selectedOrg === org.id ? 'bg-indigo-600 text-white dark:text-[#ffffff]' : 'bg-gray-100 text-gray-600 hover:bg-gray-200')}>{org.name}</button>
        ))}
      </div>

      {displayProjects.length === 0 ? (
        <Card><EmptyState icon={<FolderKanban className="h-12 w-12" />} title="No projects yet" description="Create your first AI security assessment project" action={selectedOrg ? { label: 'Create Project', onClick: () => setShowCreate(true) } : undefined} /></Card>
      ) : (
         
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          {displayProjects.map((project: any) => (
            <Card key={project.id} hover onClick={() => navigate(`/projects/${project.id}`)}>
              <CardHeader>
                <div className="flex items-center gap-3">
                  <div className="h-10 w-10 rounded-lg bg-cyan-100 flex items-center justify-center"><FolderKanban className="h-5 w-5 text-cyan-600" /></div>
                  <div>
                    <CardTitle className="text-base">{project.name}</CardTitle>
                    <p className="text-xs text-gray-500">{project.project_type?.replace(/_/g, ' ')}</p>
                  </div>
                </div>
                <Badge variant={project.status === 'active' ? 'success' : 'default'}>{project.status}</Badge>
              </CardHeader>
              <CardContent>
                <p className="text-sm text-gray-600 line-clamp-2 mb-3">{project.description || 'No description'}</p>
                <div className="text-xs text-gray-500">Created {formatDate(project.created_at)}</div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {showCreate && <CreateProjectModal orgId={selectedOrg} onClose={() => setShowCreate(false)} />}
    </div>
  )
}

function CreateProjectModal({ orgId, onClose }: { orgId: string; onClose: () => void }) {
  const { createProject, isLoading } = useProjectStore()
  const [name, setName] = useState('')
  const [description, setDescription] = useState('')
  const [projectType, setProjectType] = useState('ai_security')

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    await createProject({ organization: orgId, name, description, project_type: projectType })
    onClose()
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
      <div className="bg-white rounded-2xl p-6 w-full max-w-md mx-4 shadow-2xl">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">Create Project</h2>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div><label className="block text-sm font-medium text-gray-700 mb-1">Name *</label><input type="text" value={name} onChange={(e) => setName(e.target.value)} required placeholder="GPT-4 Security Assessment" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500" /></div>
          <div><label className="block text-sm font-medium text-gray-700 mb-1">Description</label><textarea value={description} onChange={(e) => setDescription(e.target.value)} rows={3} placeholder="Project description" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500" /></div>
          <div><label className="block text-sm font-medium text-gray-700 mb-1">Type</label><select value={projectType} onChange={(e) => setProjectType(e.target.value)} className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500"><option value="ai_security">AI Security Assessment</option><option value="compliance">Compliance Assessment</option><option value="audit">Security Audit</option><option value="custom">Custom</option></select></div>
          <div className="flex justify-end gap-3 pt-2"><Button variant="outline" type="button" onClick={onClose}>Cancel</Button><Button type="submit" isLoading={isLoading}>Create</Button></div>
        </form>
      </div>
    </div>
  )
}
